// ============================================================================
// C_PHY_apb: APB4 register wrapper around C_PHY_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/C_PHY.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/C_PHY.md
// ============================================================================
module C_PHY_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [1:0] t_a,
  output logic [1:0] t_b,
  output logic [1:0] t_c,
  input logic [1:0] r_a,
  input logic [1:0] r_b,
  input logic [1:0] r_c
);
  localparam logic [31:0] ID_VALUE = 32'h43700200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [8:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd9) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_irq;
  logic          c_irq_clear;
  logic [15:0]   c_tx_data;
  logic          c_tx_valid;
  logic          c_tx_ready;
  logic          c_tx_last;
  logic          c_tx_done;
  logic          c_rx_active;
  logic [15:0]   c_rx_data;
  logic          c_rx_valid;
  logic          c_rx_done;
  C_PHY_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .irq(c_irq),
    .irq_clear(c_irq_clear),
    .tx_data(c_tx_data),
    .tx_valid(c_tx_valid),
    .tx_ready(c_tx_ready),
    .tx_last(c_tx_last),
    .tx_done(c_tx_done),
    .t_a(t_a),
    .t_b(t_b),
    .t_c(t_c),
    .r_a(r_a),
    .r_b(r_b),
    .r_c(r_c),
    .rx_active(c_rx_active),
    .rx_data(c_rx_data),
    .rx_valid(c_rx_valid),
    .rx_done(c_rx_done)
  );

  // ---------------- registers ----------------
  logic [6:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [16:0] h_TX;   // 12'h014 TX holding register
  logic [15:0] h_RX;   // 12'h018 RX holding register
  logic [0:0] p_CMD;   // 12'h01C CMD (pulses)
  logic full_TX;
  logic avail_RX;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      h_TX <= '0;
      h_RX <= '0;
      p_CMD <= '0;
      full_TX <= 1'b0;
      avail_RX <= 1'b0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[6:0] & wmask[6:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      p_CMD <= (wr && hit[7]) ? PWDATA[0:0] & wmask[0:0] : '0;
      if (wr && hit[5] && !full_TX) h_TX <= (h_TX & ~wmask[16:0]) | (PWDATA[16:0] & wmask[16:0]);
      if (wr && hit[5] && !full_TX) full_TX <= 1'b1;
      else if (full_TX && c_tx_ready) full_TX <= 1'b0;
      if (c_rx_valid && (!avail_RX || (rd && hit[6]))) begin
        h_RX[15:0] <= c_rx_data[15:0];
        avail_RX <= 1'b1;
      end else if (rd && hit[6]) avail_RX <= 1'b0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_tx_data[15:0] = h_TX[15:0];
  assign c_tx_last = h_TX[16:16];
  assign c_irq_clear = p_CMD;
  assign c_tx_valid = full_TX;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_tx_done;
    irq_set[1] = c_rx_done;
    irq_set[2] = c_irq;
    irq_set[3] = full_TX & c_tx_ready;
    irq_set[4] = wr & (hit[5]) & full_TX;
    irq_set[5] = c_rx_valid & (~avail_RX | (rd & hit[6]));
    irq_set[6] = c_rx_valid & avail_RX & ~(rd & hit[6]);
  end
  assign irq = |(irq_status & irq_enable);
  wire [1:0] flags = {avail_RX, full_TX};

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd3: apb_rdata = 32'(flags);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(h_TX);
      10'd6: apb_rdata = 32'(h_RX);
      10'd8: apb_rdata = 32'({c_rx_active});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
